from fastapi import FastAPI
import pytest
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/vibe")
def read_vibe():
    return {"vibe": "good"}

client = TestClient(app)

def test_vibe():
    # We need to use a client that can send a VIBE request.
    # httpx (used by TestClient) might not support VIBE by default,
    # but we can try to send it.
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"vibe": "good"}

if __name__ == "__main__":
    try:
        test_vibe()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
